class TestViewDeserializer {
    constructor(f) {
        this.f = f;
        this.e = new Map();
    }
    fromJSON(json) {
        const view = this.f.add(new TestSerializableView(json.name, 50, Number.MAX_VALUE, 50, Number.MAX_VALUE));
        this.e.set(json.name, view);
        return view;
    }
    getView(id) {
        const view = this.e.get(id);
        if (!view) {
            throw new Error('Unknown view');
        }
        return view;
    }
